const items = $input.all();
const normalizedJobs = [];
const today = new Date().toISOString().split('T')[0];
const seen = new Set();

const KEYWORDS = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data analyst','remote data scientist',
  'remote ai marketing','remote marketing analyst','remote growth analyst',
  'remote bi analyst','remote automation','remote ai workflow',
  'data analyst','data scientist','business intelligence','bi analyst',
  'marketing analyst','growth analyst','performance marketing',
  'ai marketing','analytics engineer','martech','digital marketing',
  'marketing automation','seo analyst','ppc analyst','ga4'
];

for (const item of items) {
  const d = item.json;
  const source = d.source || 'unknown';
  const raw = d.raw_data || d;
  let jobs = [];

  if (source === 'remoteok') {
    const list = Array.isArray(raw) ? raw : (Array.isArray(raw[0]) ? raw[0] : [raw]);
    for (const j of list) {
      if (!j || !j.position) continue;
      jobs.push({
        job_id: `remoteok_${j.id || j.slug || Date.now()}`,
        job_title: j.position || '',
        company: j.company || '',
        job_url: j.url || `https://remoteok.com/l/${j.slug || j.id}`,
        source: 'Remote OK',
        location_text: j.location || 'Worldwide',
        salary: j.salary || '',
        description: (j.description || '') + ' ' + (j.tags ? j.tags.join(' ') : ''),
        posted_date: j.date ? j.date.split('T')[0] : today,
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
      });
    }
  } else if (source === 'remotive') {
    const list = raw.jobs || (Array.isArray(raw) ? raw : []);
    for (const j of list) {
      if (!j || !j.title) continue;
      jobs.push({
        job_id: `remotive_${j.id}`,
        job_title: j.title || '',
        company: j.company_name || '',
        job_url: j.url || '',
        source: 'Remotive',
        location_text: j.candidate_required_location || 'Worldwide',
        salary: j.salary || '',
        description: j.description || '',
        posted_date: j.publication_date ? j.publication_date.split('T')[0] : today,
        tags: j.tags ? j.tags.join(', ') : (j.category || '')
      });
    }
  } else if (source === 'weworkremotely') {
    const urlHash = (raw.link || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0);
    jobs.push({
      job_id: `wwr_${urlHash}`,
      job_title: (raw.title || '').replace(/<[^>]*>/g, '').trim(),
      company: raw.creator || raw['dc:creator'] || '',
      job_url: raw.link || '',
      source: 'We Work Remotely',
      location_text: 'Remote',
      salary: '',
      description: (raw.content || raw.summary || raw.description || '').replace(/<[^>]*>/g, ' '),
      posted_date: raw.pubDate ? new Date(raw.pubDate).toISOString().split('T')[0] : today,
      tags: Array.isArray(raw.categories) ? raw.categories.join(', ') : ''
    });
  } else if (source === 'himalayas') {
    const list = raw.jobs || (Array.isArray(raw) ? raw : []);
    for (const j of list) {
      if (!j || !j.title) continue;
      jobs.push({
        job_id: `himalayas_${j.slug || j.id}`,
        job_title: j.title || '',
        company: (j.company && j.company.name) ? j.company.name : (j.companyName || ''),
        job_url: j.applicationUrl || `https://himalayas.app/jobs/${j.slug}`,
        source: 'Himalayas',
        location_text: j.location || 'Worldwide',
        salary: j.compensation || '',
        description: j.description || '',
        posted_date: j.publishedAt ? j.publishedAt.split('T')[0] : today,
        tags: Array.isArray(j.categories) ? j.categories.join(', ') : ''
      });
    }
  } else if (source === 'dynamite') {
    const urlHash = (raw.link || '').split('').reduce((a, c) => a + c.charCodeAt(0), 0);
    jobs.push({
      job_id: `dynamite_${urlHash}`,
      job_title: (raw.title || '').replace(/<[^>]*>/g, '').trim(),
      company: raw.creator || '',
      job_url: raw.link || '',
      source: 'Dynamite Jobs',
      location_text: 'Remote',
      salary: '',
      description: (raw.content || raw.description || '').replace(/<[^>]*>/g, ' '),
      posted_date: raw.pubDate ? new Date(raw.pubDate).toISOString().split('T')[0] : today,
      tags: Array.isArray(raw.categories) ? raw.categories.join(', ') : ''
    });
  }

  for (const job of jobs) {
    if (!job.job_title || !job.job_url) continue;
    if (seen.has(job.job_url)) continue;
    const fullText = `${job.job_title} ${job.description} ${job.tags} ${job.location_text}`.toLowerCase();
    const hasKeyword = KEYWORDS.some(kw => fullText.includes(kw));
    if (!hasKeyword) continue;
    seen.add(job.job_url);
    job.date_found = today;
    job.item_type = 'new';
    normalizedJobs.push({ json: job });
  }
}

return normalizedJobs;

const allItems = $input.all();
const existingItems = allItems.filter(i => i.json.item_type === 'existing');
const newItems = allItems.filter(i => i.json.item_type === 'new');

const existingUrls = new Set(existingItems.map(i => i.json.job_url).filter(Boolean));
const existingKeys = new Set(
  existingItems
    .map(i => `${(i.json.company || '').toLowerCase().trim()}::${(i.json.job_title || '').toLowerCase().trim()}`)
    .filter(k => k !== '::')
);

const HARD_REJECT = [
  /\bus[- ]only\b/i, /\bcanada[- ]only\b/i, /\buk[- ]only\b/i,
  /\beu[- ]only\b/i, /\beurope[- ]only\b/i, /\baustralia[- ]only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i,
  /\bmust be authorized to work in\b/i, /\bwork authorization required\b/i,
  /\blocal work permit required\b/i, /\bwork permit required\b/i,
  /\beligible to work in the (us|uk|eu|canada|australia)\b/i,
  /\b(us|uk|eu|ca|au) citizens? only\b/i,
  /\boffice required\b/i, /\bonsite required\b/i,
  /\bhybrid.{0,30}required\b/i,
  /\bremote within.{0,20}only\b/i,
  /\bfixed (us|est|pst|cst|cet|gmt) hours\b/i,
  /\bmust relocate\b/i, /\brelocation required\b/i
];

const deduped = [];
const seenThisRun = new Set();

for (const item of newItems) {
  const job = item.json;
  if (!job.job_url || !job.job_title) continue;
  if (existingUrls.has(job.job_url)) continue;
  if (seenThisRun.has(job.job_url)) continue;
  const dedupeKey = `${(job.company || '').toLowerCase().trim()}::${(job.job_title || '').toLowerCase().trim()}`;
  if (existingKeys.has(dedupeKey)) continue;
  seenThisRun.add(job.job_url);

  const fullText = `${job.job_title} ${job.location_text} ${job.description} ${job.tags}`.toLowerCase();
  let hardRejected = false;
  for (const pattern of HARD_REJECT) {
    if (pattern.test(fullText)) { hardRejected = true; break; }
  }
  if (hardRejected) continue;

  deduped.push({ json: { ...job, item_type: undefined } });
}

return deduped;

const items = $input.all();
return items.map(item => {
  const job = item.json;
  const desc = (job.description || '').substring(0, 2000);
  const prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

REJECT the job if it:
- Requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote within one country only
- Requires fixed working hours forcing Jerry to work midnight to 9am Taiwan time

KEEP the job only if:
- It says worldwide remote, work from anywhere, global remote, or APAC remote
- It allows international contractors anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or similar
- There is no geographic restriction mentioned

Return ONLY valid JSON (no markdown, no explanation):
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "one short sentence",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job Title: ${job.job_title}
Company: ${job.company}
Location Text: ${job.location_text}
Tags: ${job.tags}

Job Description:
${desc}`;
  return {
    json: { ...job, ai_prompt: prompt }
  };
});

const items = $input.all();
const prevItems = $('Prepare AI Prompt').all();
const results = [];

const ASYNC_HIGH = ['async', 'asynchronous'];
const ASYNC_MED = ['flexible hours', 'flexible schedule', 'work across time zones', 'own schedule', 'low meeting'];
const ASYNC_LOW = ['distributed team', 'remote first', 'remote-first'];
const ASYNC_REJECT = [
  'strict 9 to 5', 'fixed us hours', 'fixed est', 'fixed pst', 'fixed cet',
  'daily live calls required', 'must overlap full business day', 'core hours 9'
];

const ROLE_HIGH = [
  'data analyst', 'data scientist', 'junior data scientist', 'business intelligence',
  'bi analyst', 'marketing analyst', 'performance marketing', 'growth analyst',
  'ai marketing', 'ai automation', 'ai workflow consultant', 'creative strategist',
  'martech', 'analytics engineer', 'marketing data'
];
const ROLE_MED = [
  'digital marketing', 'marketing', 'analytics', 'seo', 'ppc', 'sem',
  'content analyst', 'automation specialist', 'reporting analyst', 'market research'
];

for (let i = 0; i < items.length; i++) {
  const aiItem = items[i];
  const jobItem = prevItems[i];
  if (!jobItem) continue;
  const job = jobItem.json;

  let aiResult = {};
  try {
    const raw = aiItem.json?.choices?.[0]?.message?.content || '{}';
    const cleaned = raw.replace(/```json\n?|\n?```/g, '').trim();
    aiResult = JSON.parse(cleaned);
  } catch(e) {
    aiResult = { taiwan_eligible: 'unclear', reason: 'Parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  }

  if (aiResult.decision === 'reject' || aiResult.taiwan_eligible === 'no') continue;

  const fullText = `${job.job_title} ${job.description} ${job.tags} ${job.location_text}`.toLowerCase();

  if (ASYNC_REJECT.some(kw => fullText.includes(kw))) continue;

  let asyncLevel = 'low';
  if (ASYNC_HIGH.some(kw => fullText.includes(kw))) asyncLevel = 'high';
  else if (ASYNC_MED.some(kw => fullText.includes(kw))) asyncLevel = 'medium';
  else if (ASYNC_LOW.some(kw => fullText.includes(kw))) asyncLevel = 'medium';

  const isHighRole = ROLE_HIGH.some(kw => fullText.includes(kw));
  const isMedRole = ROLE_MED.some(kw => fullText.includes(kw));
  const roleCategory = isHighRole ? 'high_fit' : (isMedRole ? 'medium_fit' : 'low_fit');

  let score = 0;

  // Taiwan eligibility (0-40)
  if (aiResult.taiwan_eligible === 'yes') {
    score += aiResult.location_risk === 'low' ? 40 : 30;
  } else if (aiResult.taiwan_eligible === 'unclear') {
    score += 20;
  }

  // Async fit (0-25)
  if (asyncLevel === 'high') score += 25;
  else if (asyncLevel === 'medium') score += 20;
  else score += 10;

  // Role fit (0-25)
  if (isHighRole) score += 25;
  else if (isMedRole) score += 15;

  // Salary (0-25)
  const salaryStr = (job.salary || '').replace(/,/g, '');
  const nums = salaryStr.match(/(\d{4,})/g) || [];
  if (nums.length > 0) {
    const topNum = Math.max(...nums.map(Number));
    const isAnnual = /year|annual|yr|\/yr/i.test(salaryStr);
    const monthly = isAnnual ? topNum / 12 : topNum;
    if (monthly >= 5000) score += 25;
    else if (monthly >= 3000) score += 15;
    else score += 10;
  }

  const fitReasons = [];
  if (aiResult.taiwan_eligible === 'yes') fitReasons.push('Taiwan eligible');
  if (aiResult.contractor_possible === 'yes') fitReasons.push('Contractor OK');
  if (asyncLevel === 'high') fitReasons.push('Fully async');
  else if (asyncLevel === 'medium') fitReasons.push('Flexible hours');
  if (isHighRole) fitReasons.push('Strong role match: ' + ROLE_HIGH.find(kw => fullText.includes(kw)));
  if (job.salary) fitReasons.push('Salary listed');

  results.push({ json: {
    ...job,
    taiwan_eligible: aiResult.taiwan_eligible,
    taiwan_reason: aiResult.reason,
    location_risk: aiResult.location_risk,
    timezone_risk: aiResult.timezone_risk,
    contractor_possible: aiResult.contractor_possible,
    async_level: asyncLevel,
    role_category: roleCategory,
    why_good_fit: fitReasons.join('; '),
    score: score,
    decision: score >= 85 ? 'apply_immediately' : (score >= 70 ? 'apply' : 'review'),
    application_status: 'new',
    notes: ''
  }});
}

results.sort((a, b) => b.json.score - a.json.score);
return results;

const items = $input.all();
const prevItems = $('IF Score 85 Plus').all(0);
const results = [];
for (let i = 0; i < items.length; i++) {
  const aiItem = items[i];
  const jobItem = prevItems[i];
  if (!jobItem) continue;
  const coverLetter = aiItem.json?.choices?.[0]?.message?.content || '';
  results.push({ json: { ...jobItem.json, cover_letter_draft: coverLetter } });
}
return results;

const allItems = $input.all();
const today = new Date().toISOString().split('T')[0];
const twDate = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', year: 'numeric', month: 'long', day: 'numeric' });

const filteredItems = allItems.filter(i =>
  i.json.score !== undefined && !i.json.date_rejected
);
const rejectedItems = allItems.filter(i => i.json.date_rejected);

const todayFiltered = filteredItems.filter(i => (i.json.date_found || '').startsWith(today));
const todayRejected = rejectedItems.filter(i => (i.json.date_rejected || '').startsWith(today));

todayFiltered.sort((a, b) => (Number(b.json.score) || 0) - (Number(a.json.score) || 0));

const topJobs = todayFiltered.slice(0, 10);
const manualCheck = todayFiltered.filter(i => i.json.taiwan_eligible === 'unclear' && Number(i.json.score) >= 70);

const rejStats = {
  us_only: todayRejected.filter(i => /us only/i.test(i.json.reason)).length,
  eu_only: todayRejected.filter(i => /eu only|europe only/i.test(i.json.reason)).length,
  hybrid: todayRejected.filter(i => /hybrid|onsite/i.test(i.json.reason)).length,
  timezone: todayRejected.filter(i => /timezone|fixed.*hours/i.test(i.json.reason)).length,
  total: todayRejected.length
};

let html = `<div style="font-family:sans-serif;max-width:700px;margin:0 auto">`;
html += `<h1 style="color:#1e3a5f">🌏 Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p style="color:#666">${twDate} &nbsp;|&nbsp; ${topJobs.length} jobs found today &nbsp;|&nbsp; ${rejStats.total} rejected</p>`;

if (topJobs.length === 0) {
  html += `<p style="color:#888">No qualifying jobs found today. All ${todayRejected.length + filteredItems.length} checked jobs were filtered out.</p>`;
} else {
  html += `<h2>🏆 Top Jobs Today</h2>`;
  topJobs.forEach((item, idx) => {
    const j = item.json;
    const scoreColor = Number(j.score) >= 85 ? '#16a34a' : '#2563eb';
    html += `<div style="border:1px solid #e2e8f0;border-radius:8px;padding:16px;margin:12px 0">`;
    html += `<h3 style="margin:0 0 8px">${idx + 1}. ${j.job_title}</h3>`;
    html += `<p style="margin:4px 0"><strong>Company:</strong> ${j.company}</p>`;
    html += `<p style="margin:4px 0"><strong>Score:</strong> <span style="color:${scoreColor};font-weight:bold">${j.score}/100</span></p>`;
    html += `<p style="margin:4px 0"><strong>Taiwan Eligible:</strong> ${j.taiwan_eligible} — ${j.taiwan_reason}</p>`;
    html += `<p style="margin:4px 0"><strong>Async Level:</strong> ${j.async_level}</p>`;
    html += `<p style="margin:4px 0"><strong>Timezone Risk:</strong> ${j.timezone_risk}</p>`;
    html += `<p style="margin:4px 0"><strong>Salary:</strong> ${j.salary || 'Not listed'}</p>`;
    html += `<p style="margin:4px 0"><strong>Why it fits Jerry:</strong> ${j.why_good_fit}</p>`;
    html += `<p style="margin:8px 0"><a href="${j.job_url}" style="background:#2563eb;color:white;padding:8px 16px;text-decoration:none;border-radius:6px;font-size:14px">Apply →</a></p>`;
    html += `</div>`;
  });
}

if (manualCheck.length > 0) {
  html += `<h2>⚠️ Manual Check Required</h2>`;
  html += `<p style="color:#666">Taiwan eligibility unclear — review before applying:</p><ul>`;
  manualCheck.forEach(item => {
    const j = item.json;
    html += `<li><a href="${j.job_url}">${j.job_title} at ${j.company}</a> (Score: ${j.score}) — ${j.taiwan_reason}</li>`;
  });
  html += `</ul>`;
}

html += `<h2>📊 Rejection Summary</h2><ul>`;
html += `<li>US only: ${rejStats.us_only}</li>`;
html += `<li>EU only: ${rejStats.eu_only}</li>`;
html += `<li>Hybrid / Onsite: ${rejStats.hybrid}</li>`;
html += `<li>Timezone conflict: ${rejStats.timezone}</li>`;
html += `<li><strong>Total rejected: ${rejStats.total}</strong></li></ul>`;
html += `<p style="color:#999;font-size:12px;margin-top:24px">Sent by Taiwan Job Hunter · Powered by n8n · ${twDate}</p></div>`;

return [{ json: {
  subject: `🌏 Taiwan Jobs ${twDate} — ${topJobs.length} matches (${todayFiltered.filter(i => Number(i.json.score) >= 85).length} high-score)`,
  body: html,
  total_found: topJobs.length,
  high_score_count: todayFiltered.filter(i => Number(i.json.score) >= 85).length
}}];
